const resendInvitation = `-- name: ResendInvitation :one
UPDATE invitations
SET token = $2, expires_at = $3, status = 'PENDING', inviter_id = $4, updated_at = CURRENT_TIMESTAMP
WHERE id = $1
RETURNING id, inviter_id, invitee_email, organization_id, workspace_id, project_id, role, status, token, expires_at, created_at, updated_at
`

type ResendInvitationParams struct {
	ID        uuid.UUID        `json:"id"`
	Token     string           `json:"token"`
	ExpiresAt pgtype.Timestamp `json:"expires_at"`
	InviterID uuid.UUID        `json:"inviter_id"`
}

func (q *Queries) ResendInvitation(ctx context.Context, arg ResendInvitationParams) (Invitation, error) {
	row := q.db.QueryRow(ctx, resendInvitation,
		arg.ID,
		arg.Token,
		arg.ExpiresAt,
		arg.InviterID,
	)
	var i Invitation
	err := row.Scan(
		&i.ID,
		&i.InviterID,
		&i.InviteeEmail,
		&i.OrganizationID,
		&i.WorkspaceID,
		&i.ProjectID,
		&i.Role,
		&i.Status,
		&i.Token,
		&i.ExpiresAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

